const WEBHOOK_SECRET = $env.WEBHOOK_SECRET || '';
// Use $input.first() — works in both Code node modes (Run Once for All Items / Each Item)
const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || item;

// Case-insensitive header lookup — Node.js lowercases all header names
const token = Object.entries(headers).find(
  ([k]) => k.toLowerCase() === 'x-gitlab-token'
)?.[1] || '';

if (!WEBHOOK_SECRET) {
  throw new Error('WEBHOOK_SECRET env var is empty or not set. Check .env + restart n8n.');
}
if (!token) {
  throw new Error('No X-Gitlab-Token header found. Headers seen: ' + Object.keys(headers).join(', '));
}
if (token !== WEBHOOK_SECRET) {
  throw new Error('Token mismatch. Expected: ' + WEBHOOK_SECRET.substring(0,3) + '... Got: ' + token.substring(0,3) + '...');
}

return [{json: body}];

const PLANE_PROJECT = JSON.parse($env.PLANE_PROJECT_DEV);
const WORKSPACE_SLUG = $env.WORKSPACE_SLUG;
// Markdown-link-aware regexes: recognize both `closes DEV-15` and linkback-mutated
// `closes [DEV-15](url)`. ISSUE_RE already matches [DEV-15](url) since `[` is not
// [A-Z0-9] (lookbehind) and `]` is not [A-Z0-9-] (lookahead).
const ISSUE_RE = /(?<![A-Z0-9])([A-Z][A-Z]+)(-?)(\d+)(?![A-Z0-9-])/g;
const CLOSE_RE = /\b(closes|fixes|resolves)\s+\[?([A-Z][A-Z]+)(-?)(\d+)\b\]?(?:\([^)]*\))?/g;
const REOPEN_RE = /\b(reopens)\s+\[?([A-Z][A-Z]+)(-?)(\d+)\b\]?(?:\([^)]*\))?/g;

function classifyMessage(message) {
  const results = [];
  const seen = new Set();
  let m;
  CLOSE_RE.lastIndex = 0;
  while ((m = CLOSE_RE.exec(message)) !== null) {
    const key = m[2] + '-' + m[4];
    if (!seen.has(key + ':close')) { results.push({issueKey: key, action: 'close'}); seen.add(key + ':close'); }
  }
  REOPEN_RE.lastIndex = 0;
  while ((m = REOPEN_RE.exec(message)) !== null) {
    const key = m[2] + '-' + m[4];
    if (!seen.has(key + ':reopen')) { results.push({issueKey: key, action: 'reopen'}); seen.add(key + ':reopen'); }
  }
  ISSUE_RE.lastIndex = 0;
  while ((m = ISSUE_RE.exec(message)) !== null) {
    const key = m[1] + '-' + m[3];
    if (!seen.has(key + ':close') && !seen.has(key + ':reopen') && !seen.has(key + ':mention')) {
      results.push({issueKey: key, action: 'mention'}); seen.add(key + ':mention');
    }
  }
  return results;
}

// Normalize Push Hook: loop commits[], extract issue references
const payload = $input.first().json;
const commits = payload.commits || [];
const branch = (payload.ref || '').replace('refs/heads/', '');
const gitlabProjectId = String((payload.project && payload.project.id) || '');
const items = [];

for (const commit of commits) {
  const msg = commit.message || '';
  const refs = classifyMessage(msg);
  for (const r of refs) {
    items.push({
      json: {
        issueKey: r.issueKey,
        action: r.action,
        commitSha: commit.id,
        commitUrl: commit.url || '',
        commitMessage: msg,
        commitTitle: commit.title || msg.split('\n')[0],
        author: (commit.author && commit.author.name) || '',
        branch: branch,
        isDefaultBranch: branch === (payload.project && payload.project.default_branch),
        gitlabProjectId: gitlabProjectId,
        source: 'push',
        planeProjectUuid: PLANE_PROJECT.uuid,
      },
    });
  }
}
return items;

const PLANE_PROJECT = JSON.parse($env.PLANE_PROJECT_DEV);
const WORKSPACE_SLUG = $env.WORKSPACE_SLUG;
// Markdown-link-aware regexes: recognize both `closes DEV-15` and linkback-mutated
// `closes [DEV-15](url)`; similarly for reopens. Bare `[DEV-15](url)` counts as
// mention via ISSUE_RE (which already matches the bracketed form).
const ISSUE_RE = /(?<![A-Z0-9])([A-Z][A-Z]+)(-?)(\d+)(?![A-Z0-9-])/g;
const CLOSE_RE = /\b(closes|fixes|resolves)\s+\[?([A-Z][A-Z]+)(-?)(\d+)\b\]?(?:\([^)]*\))?/g;
const REOPEN_RE = /\b(reopens)\s+\[?([A-Z][A-Z]+)(-?)(\d+)\b\]?(?:\([^)]*\))?/g;

function classifyMessage(message) {
  const results = [];
  const seen = new Set();
  let m;
  CLOSE_RE.lastIndex = 0;
  while ((m = CLOSE_RE.exec(message)) !== null) {
    const key = m[2] + '-' + m[4];
    if (!seen.has(key + ':close')) { results.push({issueKey: key, action: 'close'}); seen.add(key + ':close'); }
  }
  REOPEN_RE.lastIndex = 0;
  while ((m = REOPEN_RE.exec(message)) !== null) {
    const key = m[2] + '-' + m[4];
    if (!seen.has(key + ':reopen')) { results.push({issueKey: key, action: 'reopen'}); seen.add(key + ':reopen'); }
  }
  ISSUE_RE.lastIndex = 0;
  while ((m = ISSUE_RE.exec(message)) !== null) {
    const key = m[1] + '-' + m[3];
    if (!seen.has(key + ':close') && !seen.has(key + ':reopen') && !seen.has(key + ':mention')) {
      results.push({issueKey: key, action: 'mention'}); seen.add(key + ':mention');
    }
  }
  return results;
}

// Normalize MR (with commits) — handles open/update/reopen/merge/close.
// Input: Get MR Commits HTTP response (commits array, both shapes).
// MR metadata: from original webhook payload via $('MR Action?').
const mrPayload = $('MR Action?').first().json;
const attrs = mrPayload.object_attributes || {};
const action = attrs.action;
const mrIid = attrs.iid;
const mrUrl = attrs.url || '';
const mrTitle = attrs.title || '';
const sourceBranch = attrs.source_branch || '';
const targetBranch = attrs.target_branch || '';
const description = attrs.description || '';
const gitlabProjectId = String((mrPayload.project && mrPayload.project.id) || '');
// Default branch of the target project. Per GitLab webhook docs, payload.project
// is the target project; for fork MRs the target also lives at attrs.target.
const defaultBranch = (mrPayload.project && mrPayload.project.default_branch)
  || (attrs.target && attrs.target.default_branch) || '';
const isMergedToDefault = action === 'merge' && targetBranch === defaultBranch;

// Collect all text sources: MR description once + every commit message.
// Handle both single-item-array and split-item response shapes from HTTP Request v4.2.
const inputAll = $input.all();
const commitsRaw = (inputAll.length === 1 && Array.isArray(inputAll[0].json))
  ? inputAll[0].json
  : inputAll.map(i => i.json);

const allRefs = classifyMessage(description);
for (const c of commitsRaw) {
  const msg = c.message || c.title || '';
  const refs = classifyMessage(msg);
  for (const r of refs) allRefs.push(r);
}

const items = [];

if (action === 'close') {
  // close: every discovered issue ref -> mr-closed (dedup by issueKey only).
  const seenKeys = new Set();
  for (const r of allRefs) {
    if (seenKeys.has(r.issueKey)) continue;
    seenKeys.add(r.issueKey);
    items.push({
      json: {
        issueKey: r.issueKey, action: 'mr-closed', mrIid: mrIid, mrUrl: mrUrl,
        mrTitle: mrTitle, sourceBranch: sourceBranch, targetBranch: targetBranch,
        mrDescription: description, gitlabProjectId: gitlabProjectId,
        source: 'mr', planeProjectUuid: PLANE_PROJECT.uuid,
      },
    });
  }
} else {
  // open/update/reopen/merge: map per action type, dedup by issueKey+mappedAction.
  const seen = new Set();
  for (const r of allRefs) {
    let act;
    if (action === 'merge') {
      if (r.action === 'close') act = isMergedToDefault ? 'merged' : 'close-in-mr';
      else if (r.action === 'reopen') act = 'reopen';
      else act = 'mention';
    } else {
      // open/update/reopen
      if (r.action === 'close') act = 'close-in-mr';
      else if (r.action === 'reopen') act = 'reopen';
      else act = 'mr-open';
    }
    const dedupKey = r.issueKey + ':' + act;
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);
    const item = {
      json: {
        issueKey: r.issueKey, action: act, mrIid: mrIid, mrUrl: mrUrl,
        mrTitle: mrTitle, sourceBranch: sourceBranch, targetBranch: targetBranch,
        mrDescription: description, gitlabProjectId: gitlabProjectId,
        source: 'mr', planeProjectUuid: PLANE_PROJECT.uuid,
      },
    };
    if (action === 'merge' && attrs.merge_commit_sha) {
      item.json.mergeCommitSha = attrs.merge_commit_sha;
    }
    items.push(item);
  }
}

return items;

const PLANE_PROJECT = JSON.parse($env.PLANE_PROJECT_DEV);
const WORKSPACE_SLUG = $env.WORKSPACE_SLUG;
// Markdown-link-aware regexes (same as Normalize MR (with commits)).
const ISSUE_RE = /(?<![A-Z0-9])([A-Z][A-Z]+)(-?)(\d+)(?![A-Z0-9-])/g;
const CLOSE_RE = /\b(closes|fixes|resolves)\s+\[?([A-Z][A-Z]+)(-?)(\d+)\b\]?(?:\([^)]*\))?/g;
const REOPEN_RE = /\b(reopens)\s+\[?([A-Z][A-Z]+)(-?)(\d+)\b\]?(?:\([^)]*\))?/g;

function classifyMessage(message) {
  const results = [];
  const seen = new Set();
  let m;
  CLOSE_RE.lastIndex = 0;
  while ((m = CLOSE_RE.exec(message)) !== null) {
    const key = m[2] + '-' + m[4];
    if (!seen.has(key + ':close')) { results.push({issueKey: key, action: 'close'}); seen.add(key + ':close'); }
  }
  REOPEN_RE.lastIndex = 0;
  while ((m = REOPEN_RE.exec(message)) !== null) {
    const key = m[2] + '-' + m[4];
    if (!seen.has(key + ':reopen')) { results.push({issueKey: key, action: 'reopen'}); seen.add(key + ':reopen'); }
  }
  ISSUE_RE.lastIndex = 0;
  while ((m = ISSUE_RE.exec(message)) !== null) {
    const key = m[1] + '-' + m[3];
    if (!seen.has(key + ':close') && !seen.has(key + ':reopen') && !seen.has(key + ':mention')) {
      results.push({issueKey: key, action: 'mention'}); seen.add(key + ':mention');
    }
  }
  return results;
}

// Normalize MR (direct) — safe terminal fallback for merge/close ONLY.
// Returns [] for any action other than merge/close. This prevents approval,
// approved, unapproval, unapproved and other non-lifecycle MR webhook actions
// from causing state changes or comments.
const payload = $input.first().json;
const attrs = payload.object_attributes || {};
const action = attrs.action;
const mrIid = attrs.iid;
const mrUrl = attrs.url || '';
const mrTitle = attrs.title || '';
const sourceBranch = attrs.source_branch || '';
const targetBranch = attrs.target_branch || '';
const description = attrs.description || '';
const gitlabProjectId = String((payload.project && payload.project.id) || attrs.target_project_id || '');
const defaultBranch = (payload.project && payload.project.default_branch)
  || (attrs.target && attrs.target.default_branch) || '';
const isMergedToDefault = action === 'merge' && targetBranch === defaultBranch;
const items = [];

if (action === 'merge') {
  const refs = classifyMessage(description);
  const lastCommitMsg = (attrs.last_commit && attrs.last_commit.message) || '';
  const lastRefs = classifyMessage(lastCommitMsg);
  const allRefs = refs.concat(lastRefs);
  const seen = new Set();
  for (const r of allRefs) {
    let act;
    if (r.action === 'close') act = isMergedToDefault ? 'merged' : 'close-in-mr';
    else if (r.action === 'reopen') act = 'reopen';
    else act = 'mention';
    const dedupKey = r.issueKey + ':' + act;
    if (seen.has(dedupKey)) continue;
    seen.add(dedupKey);
    items.push({
      json: {
        issueKey: r.issueKey, action: act, mrIid: mrIid, mrUrl: mrUrl,
        mrTitle: mrTitle, mergeCommitSha: attrs.merge_commit_sha || '',
        mrDescription: description, gitlabProjectId: gitlabProjectId,
        source: 'mr', planeProjectUuid: PLANE_PROJECT.uuid,
      },
    });
  }
} else if (action === 'close') {
  const refs = classifyMessage(description);
  const lastCommitMsg = (attrs.last_commit && attrs.last_commit.message) || '';
  const lastRefs = classifyMessage(lastCommitMsg);
  const allRefs = refs.concat(lastRefs);
  const seenKeys = new Set();
  for (const r of allRefs) {
    if (seenKeys.has(r.issueKey)) continue;
    seenKeys.add(r.issueKey);
    items.push({
      json: {
        issueKey: r.issueKey, action: 'mr-closed', mrIid: mrIid, mrUrl: mrUrl,
        mrTitle: mrTitle, mrDescription: description, gitlabProjectId: gitlabProjectId,
        source: 'mr', planeProjectUuid: PLANE_PROJECT.uuid,
      },
    });
  }
}
// Any other action (approval, approved, unapproval, unapproved, etc.) -> return []
return items;

const PLANE_PROJECT = JSON.parse($env.PLANE_PROJECT_DEV);
const WORKSPACE_SLUG = $env.WORKSPACE_SLUG;
// Markdown-link-aware regexes (kept for consistency; not called in reducer).
const ISSUE_RE = /(?<![A-Z0-9])([A-Z][A-Z]+)(-?)(\d+)(?![A-Z0-9-])/g;
const CLOSE_RE = /\b(closes|fixes|resolves)\s+\[?([A-Z][A-Z]+)(-?)(\d+)\b\]?(?:\([^)]*\))?/g;
const REOPEN_RE = /\b(reopens)\s+\[?([A-Z][A-Z]+)(-?)(\d+)\b\]?(?:\([^)]*\))?/g;

function classifyMessage(message) {
  const results = [];
  const seen = new Set();
  let m;
  CLOSE_RE.lastIndex = 0;
  while ((m = CLOSE_RE.exec(message)) !== null) {
    const key = m[2] + '-' + m[4];
    if (!seen.has(key + ':close')) { results.push({issueKey: key, action: 'close'}); seen.add(key + ':close'); }
  }
  REOPEN_RE.lastIndex = 0;
  while ((m = REOPEN_RE.exec(message)) !== null) {
    const key = m[2] + '-' + m[4];
    if (!seen.has(key + ':reopen')) { results.push({issueKey: key, action: 'reopen'}); seen.add(key + ':reopen'); }
  }
  ISSUE_RE.lastIndex = 0;
  while ((m = ISSUE_RE.exec(message)) !== null) {
    const key = m[1] + '-' + m[3];
    if (!seen.has(key + ':close') && !seen.has(key + ':reopen') && !seen.has(key + ':mention')) {
      results.push({issueKey: key, action: 'mention'}); seen.add(key + ':mention');
    }
  }
  return results;
}

// REDUCER: group raw actions by issue, apply precedence + guards.
// Precedence (highest first):
//   reopen > merged/close-on-default > close-in-mr/close-on-feature > mr-open > mention > mr-closed
const allItems = $input.all ? $input.all().map(i => i.json) : [];
if (!allItems.length) return [];
const isBackstop = allItems[0].isBackstop || false;

const groups = {};
for (const item of allItems) {
  const key = item.issueKey;
  if (!groups[key]) groups[key] = [];
  groups[key].push(item);
}

const projStates = PLANE_PROJECT.states;
const results = [];
for (const issueKey of Object.keys(groups)) {
  const actions = groups[issueKey];

  const hasReopen = actions.some(a => a.action === 'reopen');
  const hasMerged = actions.some(a => a.action === 'merged');
  const hasCloseInMr = actions.some(a => a.action === 'close-in-mr');
  const hasMrOpen = actions.some(a => a.action === 'mr-open');
  const hasMention = actions.some(a => a.action === 'mention');
  const hasClose = actions.some(a => a.action === 'close');
  const hasMrClosed = actions.some(a => a.action === 'mr-closed');

  // close on default branch = already merged -> Done; close on feature branch -> In Review
  const hasCloseOnDefault = actions.some(a => a.action === 'close' && a.isDefaultBranch);
  const hasCloseOnFeature = actions.some(a => a.action === 'close' && !a.isDefaultBranch);

  let desiredState = null;
  let actionLabel = '';
  let commentParts = [];

  if (hasReopen) {
    desiredState = projStates.inProgress; actionLabel = 'reopen';
  } else if (hasMerged || hasCloseOnDefault) {
    desiredState = projStates.done; actionLabel = hasMerged ? 'merged' : 'close';
  } else if (hasCloseInMr || hasCloseOnFeature) {
    desiredState = projStates.inReview; actionLabel = 'close';
  } else if (hasMrOpen) {
    desiredState = projStates.inProgress; actionLabel = 'mr-open';
  } else if (hasMention) {
    desiredState = projStates.inProgress; actionLabel = 'mention';
  } else if (hasMrClosed) {
    desiredState = projStates.todo; actionLabel = 'mr-closed';
  }
  if (!desiredState) continue;

  for (const a of actions) {
    if (a.source === 'push' && a.commitUrl) {
      const shaShort = (a.commitSha || '').substring(0, 7);
      commentParts.push(`mentioned in commit <a href="${a.commitUrl}">${shaShort}</a> by ${a.author || 'unknown'}: <i>${a.commitTitle || ''}</i>`);
    } else if (a.source === 'mr' && a.mrUrl) {
      commentParts.push(`MR <a href="${a.mrUrl}">!${a.mrIid || ''}: ${a.mrTitle || ''}</a>`);
    }
  }

  let externalId;
  const mrAction = actions.find(x => x.source === 'mr');
  if (mrAction) {
    externalId = `gitlab-mr-${mrAction.mrIid}-${actionLabel}-${issueKey}`;
  } else {
    const pushAction = actions.find(x => x.source === 'push' && x.commitSha);
    externalId = `gitlab-commit-${(pushAction && pushAction.commitSha) || 'unknown'}-${issueKey}`;
  }

  let shouldChangeState = true;
  let guardReason = '';
  if (isBackstop && (actionLabel === 'mr-closed')) {
    shouldChangeState = false;
    guardReason = 'backstop: mr-closed downgrade not allowed in backstop mode';
  }

  const sentinel = `<!-- n8n-bridge: src=${actions[0].source}, action=${actionLabel}, issue=${issueKey} -->`;

  results.push({
    json: {
      issueKey: issueKey,
      desiredStateName: actionLabel,
      targetStateUuid: desiredState,
      shouldChangeState: shouldChangeState,
      guardReason: guardReason,
      commentHtml: sentinel + '\n' + commentParts.join('<br>\n'),
      externalId: externalId,
      externalSource: 'gitlab',
      mrUrl: actions.find(x => x.mrUrl) ? actions.find(x => x.mrUrl).mrUrl : '',
      mrTitle: actions.find(x => x.mrTitle) ? actions.find(x => x.mrTitle).mrTitle : '',
      gitlabProjectId: actions.find(x => x.gitlabProjectId) ? actions.find(x => x.gitlabProjectId).gitlabProjectId : '',
      commitShas: actions.filter(x => x.source === 'push' && x.commitSha).map(x => x.commitSha),
      mrIid: actions.find(x => x.mrIid) ? actions.find(x => x.mrIid).mrIid : '',
      mrDescription: actions.find(x => x.mrDescription) ? actions.find(x => x.mrDescription).mrDescription : '',
      isBackstop: isBackstop,
      planeProjectUuid: PLANE_PROJECT.uuid,
    },
  });
}
return results;

const PLANE_PROJECT = JSON.parse($env.PLANE_PROJECT_DEV);
const WORKSPACE_SLUG = $env.WORKSPACE_SLUG;

const projStates = PLANE_PROJECT.states;
const stateNameByUuid = {};
for (const k of Object.keys(projStates)) stateNameByUuid[projStates[k]] = k;

// runOnceForAllItems: iterate every work item returned by Get Work Item and pair
// each to its Reducer decision via the work item's pairedItem index (which points
// back through Get Work Item to the Reducer output). Fall back to the same index.
const workItems = $input.all();
const reducerItems = $('Reducer').all();

function getPairedIndex(item, fallback) {
  const pi = item.pairedItem;
  if (!pi) return fallback;
  const p = Array.isArray(pi) ? pi[0] : pi;
  if (p && typeof p.item === 'number') return p.item;
  if (p && p.item !== undefined) { const n = Number(p.item); if (!isNaN(n)) return n; }
  return fallback;
}

const results = [];
for (let i = 0; i < workItems.length; i++) {
  const wiItem = workItems[i];
  const wi = (wiItem && wiItem.json) ? wiItem.json : {};

  const rIndex = getPairedIndex(wiItem, i);
  const reducerItem = reducerItems[rIndex];
  const r = (reducerItem && reducerItem.json) ? reducerItem.json : null;

  // Validate required fields. Throw rather than constructing undefined URLs.
  if (!r) {
    throw new Error(`Apply Guards: no Reducer decision paired for work item index ${i} (pairedItem=${rIndex})`);
  }
  if (!r.issueKey || !r.targetStateUuid || !r.externalId || !r.commentHtml) {
    throw new Error(`Apply Guards: malformed Reducer decision at index ${rIndex}: missing required fields`);
  }
  if (!wi.id || !wi.project || !wi.state) {
    throw new Error(`Apply Guards: malformed Plane work item at index ${i}: missing id/project/state`);
  }

  const currentStateName = stateNameByUuid[wi.state] || 'unknown';
  const targetStateName = stateNameByUuid[r.targetStateUuid] || 'unknown';
  const actionLabel = r.desiredStateName || '';

  let shouldChangeState = r.shouldChangeState;
  let guardReason = r.guardReason || '';

  // Protections (always applied). Comments still emit for protected states —
  // only the state change is suppressed.
  if (currentStateName === 'cancelled') {
    shouldChangeState = false; guardReason = 'protected: Cancelled is human-owned';
  } else if (currentStateName === 'done' && actionLabel !== 'reopen') {
    shouldChangeState = false; guardReason = 'protected: Done cannot be downgraded except by reopen';
  } else if (currentStateName === 'inReview' && (actionLabel === 'mention' || actionLabel === 'mr-open')) {
    shouldChangeState = false; guardReason = 'protected: In Review not downgraded by bare mention';
  } else if (wi.state === r.targetStateUuid) {
    shouldChangeState = false; guardReason = 'already in target state';
  } else if (actionLabel === 'mr-closed' && currentStateName !== 'inProgress' && currentStateName !== 'inReview') {
    shouldChangeState = false; guardReason = 'mr-closed: can only downgrade from In Progress/In Review';
  }

  results.push({
    json: {
      issueKey: r.issueKey,
      workItemId: wi.id,
      project: wi.project,
      currentState: wi.state,
      currentStateName: currentStateName,
      targetStateUuid: r.targetStateUuid,
      targetStateName: targetStateName,
      shouldChangeState: shouldChangeState,
      guardReason: guardReason,
      commentHtml: r.commentHtml,
      externalId: r.externalId,
      externalSource: r.externalSource || 'gitlab',
      mrUrl: r.mrUrl || '',
      mrTitle: r.mrTitle || '',
      gitlabProjectId: r.gitlabProjectId || '',
      commitShas: r.commitShas || [],
      mrIid: r.mrIid || '',
      mrDescription: r.mrDescription || '',
      workItemUrl: `https://plane.nforensic.site/${WORKSPACE_SLUG}/browse/${r.issueKey}/`,
    },
    pairedItem: { item: i },
  });
}
return results;

// Group Apply Guards output by commit SHA / MR IID, build GitLab link-back payloads
const allItems = $input.all().map(i => i.json);
const commits = {};  // sha -> { gitlabProjectId, issues: [{key, url}] }
const mrs = {};      // mrIid -> { gitlabProjectId, description, issues: [{key, url}] }

for (const item of allItems) {
  const url = item.workItemUrl || '';
  const key = item.issueKey || '';
  // Commits
  if (item.commitShas && item.commitShas.length > 0) {
    for (const sha of item.commitShas) {
      if (!commits[sha]) commits[sha] = { gitlabProjectId: item.gitlabProjectId, issues: [] };
      if (!commits[sha].issues.find(i => i.key === key)) commits[sha].issues.push({ key, url });
    }
  }
  // MRs
  if (item.mrIid && item.mrDescription) {
    if (!mrs[item.mrIid]) mrs[item.mrIid] = { gitlabProjectId: item.gitlabProjectId, description: item.mrDescription, issues: [] };
    if (!mrs[item.mrIid].issues.find(i => i.key === key)) mrs[item.mrIid].issues.push({ key, url });
  }
}

const results = [];
// Commit comment payloads
for (const sha of Object.keys(commits)) {
  const c = commits[sha];
  if (!c.gitlabProjectId) continue;
  const note = c.issues.map(i => `[${i.key}](${i.url})`).join(' · ');
  results.push({ json: { linkType: 'commit', gitlabProjectId: c.gitlabProjectId, commitSha: sha, note: note } });
}
  // MR description edit payloads
for (const iid of Object.keys(mrs)) {
  const mr = mrs[iid];
  if (!mr.gitlabProjectId) continue;
  let desc = mr.description;
  for (const issue of mr.issues) {
    // Idempotent + URL-safe linkback.
    // 1) If the description already contains [<issueKey>](, skip this issue entirely
    //    — it has already been linkbacked (or a user added a manual link).
    if (desc.includes(`[${issue.key}](`)) continue;
    // 2) Otherwise replace plain issue-key occurrences only when they are NOT already
    //    bracketed and NOT part of a URL/path segment. Use a prefix-capturing regex
    //    that excludes '[', '/', and uppercase alphanumeric chars before the key, and
    //    excludes '](' after. Reinsert the captured prefix to avoid lookbehind fragility.
    //    The negated character class [^A-Z0-9\[/] ensures we don't match inside a URL
    //    path (preceded by '/') or inside an existing markdown label (preceded by '['),
    //    and doesn't match when the key is preceded directly by uppercase alnum.
    const re = new RegExp('([^A-Z0-9\\[/])(' + issue.key + ')(?!\\]\\()', 'g');
    desc = desc.replace(re, `$1[${issue.key}](${issue.url})`);
  }
  results.push({ json: { linkType: 'mr', gitlabProjectId: mr.gitlabProjectId, mrIid: iid, newDescription: desc } });
}
return results;

// Validate the Plane Create Comment HTTP response. Accept only 2xx and 409
// (409 = duplicate external_id, the expected idempotency hit). Any other status
// is a real failure — throw so the workflow stops. Return the original Apply
// Guards candidate (recovered via paired-item linkage) so the branch output
// remains usable downstream.
const responses = $input.all();
const guardItems = $('Apply Guards').all();

function getPairedIndex(item, fallback) {
  const pi = item.pairedItem;
  if (!pi) return fallback;
  const p = Array.isArray(pi) ? pi[0] : pi;
  if (p && typeof p.item === 'number') return p.item;
  if (p && p.item !== undefined) { const n = Number(p.item); if (!isNaN(n)) return n; }
  return fallback;
}

const results = [];
for (let i = 0; i < responses.length; i++) {
  const respItem = responses[i];
  const body = (respItem && respItem.json) ? respItem.json : {};
  const statusCode = body.statusCode;

  if (statusCode === undefined || !((statusCode >= 200 && statusCode < 300) || statusCode === 409)) {
    throw new Error(`Validate Comment Result: unexpected Plane comment status ${statusCode}`);
  }

  const gIndex = getPairedIndex(respItem, i);
  const candidateItem = guardItems[gIndex];
  const candidate = (candidateItem && candidateItem.json) ? candidateItem.json : null;
  if (!candidate) {
    throw new Error(`Validate Comment Result: no Apply Guards candidate at index ${gIndex}`);
  }

  results.push({
    json: {
      ...candidate,
      commentStatusCode: statusCode,
      commentIdempotent: statusCode === 409,
    },
    pairedItem: { item: gIndex },
  });
}
return results;
